bool execute_arm_data_processing_immediate(std::uint32_t i,Arm9State*s){if(!s||((i>>25)&7u)!=1u)return false;unsigned cond=i>>28;if(cond==15u)return false;unsigned op=(i>>21)&15u;if(op!=0&&op!=1&&op!=2&&op!=4&&op!=10&&op!=12&&op!=13)return false;if(!arm_condition_passed(cond,s))return true;bool sf=((i>>20)&1u)!=0u;unsigned rn=(i>>16)&15u,rd=(i>>12)&15u,rot=((i>>8)&15u)*2u;std::uint32_t imm=ror(i&255u,rot),left=0;if(rd==15u||((op!=13u)&&(op!=10u)&&rn==15u))return false;if(op!=13u&&!s->read_register(rn,&left))return false;std::uint32_t r=0;bool writes=true,arith=false;switch(op){case 0:r=left&imm;break;case 1:r=left^imm;break;case 2:r=left-imm;arith=true;break;case 4:r=left+imm;arith=true;break;case 10:r=left-imm;arith=true;writes=false;break;case 12:r=left|imm;break;case 13:r=imm;break;default:return false;}if(writes&&!s->write_register(rd,r))return false;if(sf||op==10){if(arith&&(op==2||op==10))subf(s,left,imm,r);else if(arith)addf(s,left,imm,r);else{nz(s,r);if(rot)s->set_flag(Arm9State::Carry,(imm&0x80000000u)!=0u);}}return true;}
